declare(strict_types=1); require_once __DIR__ . '/../models/Resource.php'; $pdo=database();$uid=null;$id=null;$path=null;try{$pdo->exec("INSERT INTO users (username,email,password_hash,status) VALUES ('RES-TEST','res-test@example.test','hash','ACTIVE')");$uid=(int)$pdo->lastInsertId();$dir='C:\\xampp\\htdocs\\CMMP\\uploads\\resources';if(!is_dir($dir))mkdir($dir,0750,true);$file='resource-test-'.bin2hex(random_bytes(3)).'.pdf';$path=$dir.'\\'.$file;file_put_contents($path,'%PDF-test');$id=Resource::create(['user_id'=>$uid,'title'=>'Test sermon','description'=>'Test','type'=>'SERMON','visibility'=>'MEMBERS','published_at'=>date('Y-m-d H:i:s'),'path'=>'uploads/resources/'.$file,'mime'=>'application/pdf','size'=>filesize($path)]);$visible=Resource::listForUser(['MEMBER']);if(count(array_filter($visible,fn($r)=>(int)$r['id']===$id))!==1)throw new RuntimeException('Member resource visibility failed.');Resource::update($id,['title'=>'Updated sermon','description'=>'Updated','type'=>'SERMON','visibility'=>'STAFF','published_at'=>date('Y-m-d H:i:s')]);$visible=Resource::listForUser(['MEMBER']);if(count(array_filter($visible,fn($r)=>(int)$r['id']===$id))!==0)throw new RuntimeException('Private resource leaked to member.');echo "Resource security smoke test passed.\n";}finally{if($path&&is_file($path))unlink($path);if($id)$pdo->prepare('DELETE FROM church_resources WHERE id=:id')->execute(['id'=>$id]);if($uid)$pdo->prepare('DELETE FROM users WHERE id=:id')->execute(['id'=>$uid]);}
